import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormControl, UntypedFormGroup, Validators } from "@angular/forms";
import { DatePipe } from "@angular/common";
import { MatPaginator } from "@angular/material/paginator";
import { MatSort } from "@angular/material/sort";
import { Router } from '@angular/router';
import { MatTableDataSource } from "@angular/material/table";
import * as XLSX from "xlsx";
import { NgxSpinnerService } from 'ngx-spinner';
import { LeavesService } from '../../leaves.service';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { Moment } from 'moment';
import * as _moment from 'moment';
import { MonthWiseLeavesDialogComponent } from '../../dialog/month-wise-leaves-dialog/month-wise-leaves-dialog.component';
import { MatDialog } from '@angular/material/dialog';
import { CompanySettingService } from 'src/app/services/companysetting.service';
import { EmsService } from 'src/app/modules/ems/ems.service';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
// import {default as _rollupMoment} from 'moment';
const moment =  _moment;

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-month-wise-employee-leaves-report',
  templateUrl: './month-wise-employee-leaves-report.component.html',
  styleUrls: ['./month-wise-employee-leaves-report.component.scss'],
  providers: [
    {provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE]},
    {provide: MAT_DATE_FORMATS, useValue: MY_FORMATS},
  ],
})
export class MonthWiseEmployeeLeavesReportComponent implements OnInit {
  constructor(
    private router: Router,
    public formBuilder: UntypedFormBuilder,
    public spinner :NgxSpinnerService,
    private RS:ReportsService,
    public dialog: MatDialog,
    private companyService: CompanySettingService,
    private emsService: EmsService,
  private LM: LeavesService,
  private pdfService: PdfHeaderService,
  public datePipe: DatePipe,) {
      this.companyDBName = sessionStorage.getItem("companyName") ? sessionStorage.getItem("companyName") : null;
   
     }
  companyDBName:any;
  viewdata:any
  date = new UntypedFormControl(moment());
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.date.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.date.setValue(ctrlValue);
    datepicker.close();
  }
  searchForm!: UntypedFormGroup;
  displayedColumns: string[] = ['sno','empid','empname','paidleaves','lopleaves','totalleaves'];
  dataSource: MatTableDataSource<any>=<any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  @ViewChild('table') table!: ElementRef;
  pageLoading = true;
  arrayList:any[]=[];
  minDate:any;
  pipe = new DatePipe('en-US');
  userSession:any;
  employeeDetails: any;
  year:any;
  max = new Date()
  searchControl = new FormControl('');
  filteredEmployees: any = [];
  worklocationDetails: any = [];
  filteredLocations: any = [];
  searchControl2 = new FormControl('');
  ngOnInit(): void {

    this.getWorkLocation()
    this.searchForm = this.formBuilder.group({
      fromDate:[''],
      location:['',Validators.required],
      employeeId:[''],
      });
      this.date = new UntypedFormControl(moment());
      this.searchForm.get('fromDate')?.valueChanges.subscribe((selectedValue:any) => {
        this.minDate = selectedValue;

    });
    // this.Searchform();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.dataSource = new MatTableDataSource(this.arrayList);

    this.searchControl.valueChanges.subscribe(searchText => {
      this.filteredLocationList(searchText);
    });
    this.searchControl2.valueChanges.subscribe(searchText => {
      this.filteredEmployeesList(searchText);
    });
    this.searchForm.get('location')?.valueChanges.subscribe((selectedValue: any) => {
      this.getEmployeelist();
  })
  }

  getWorkLocation() {
    this.companyService.getactiveWorkLocation({ id: null, companyName: this.companyDBName }).subscribe((result) => {
      this.worklocationDetails = result.data;
      this.filteredLocations = this.worklocationDetails;
    })
  }

  exportAsXLSX() {
    let year = this.date.value._d.getFullYear();
    let month = this.date.value._d.getMonth()+1;
  
    // Format the data to match the required columns
    const exportData = this.arrayList.map((row, index) => ({
      "S.No": index + 1,
      "Emp.Id":row.empid,
      "Emp. Name": row.empname,
      "Paid Leaves": row.approved_leaves.slice(0,-1),
      "LOP Leaves": row.lopcount.slice(0,-1),
      "Total": row.total_leaves.slice(0,-1),
    }));
  
    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
  
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'monthly_employee_leaves_report');
  
    /* save to file */
    XLSX.writeFile(wb, month + " - " + year + " - " + 'monthly_employee_leaves_report.xlsx');
  

  }

  getEmployeelist(){
    this.employeeDetails = [];
    let  locationId = this.searchForm.controls.location.value;
    this.emsService.getEmployeeDirectoryList(locationId).subscribe((res: any) => {
      if (res.status && res.data.length != 0) {
        this.employeeDetails = res.data;
        this.filteredEmployees = this.employeeDetails
        this.searchForm.controls.employeeId.setValue('0');
      }
    })
  }

  Searchform(){
   
    if(this.searchForm.valid){
    this.arrayList=[];
    let empid =  this.searchForm.controls.employeeId.value == 0 ? 0 : this.searchForm.controls.employeeId.value;
    let data ={
      locationId: this.searchForm.controls.location.value,
      year: this.date.value._d.getFullYear(),
      month: this.date.value._d.getMonth()+1,
      employeeId: empid,
      
    }
    this.spinner.show();
    this.LM.getEmployeeUtilizedLeaveCount(data).subscribe((res:any)=>{
      if(res.status && res.data.length > 0){
        this.arrayList = res.data;
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.paginator.pageSize=5;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
        this.spinner.hide();
      }
      else {
        this.arrayList = [];
        this.dataSource = new MatTableDataSource(this.arrayList);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading=false;
        this.spinner.hide();
      }
    })
    this.spinner.hide();
    }
   }

  resetform(){
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
          this.router.navigate(["/LeaveManagement/monthlyLeavesReport"]));
    }
  getPageSizes(): number[] {
     
  var customPageSizeArray = [];
  if (this.dataSource.data.length > 5) {
    customPageSizeArray.push(5);
  }
  if (this.dataSource.data.length > 10) {
    customPageSizeArray.push(10);
  }
  if (this.dataSource.data.length > 20) {
    customPageSizeArray.push(20);
  }
  customPageSizeArray.push(this.dataSource.data.length);
  return customPageSizeArray;
  }

  filteredEmployeesList(searchText: any) {
    this.filteredEmployees = this.employeeDetails.filter((val:any) =>
      val.empid.toLowerCase().includes(searchText.toLowerCase()) ||
      val.ename.toLowerCase().includes(searchText.toLowerCase())
    );
    if(this.filteredEmployees.length<=0){
      this.searchControl2.setValue('');
    }else{
      
    }
  }

  view(data:any){
    let givenData = {
      "rm_id_value":1,
      "date_value":data,
    }
          let dialogRef = this.dialog.open(MonthWiseLeavesDialogComponent, {
              width: '500px',position:{top:`100px`},
              disableClose: true,
              data:givenData

            });
  }

  filteredLocationList(searchText: any) {
    this.filteredLocations = this.worklocationDetails.filter((val:any) =>
      val.location.toLowerCase().includes(searchText.toLowerCase()) ||
      val.cityname.toLowerCase().includes(searchText.toLowerCase())
    );
    if(this.filteredLocations.length<=0){
      this.searchControl.setValue('');
    }else{
      
    }
  }

  generatePDF() {
  
    const doc = new jsPDF({ orientation: 'landscape' });
    const reportName = 'Monthly Leaves Report';
    let formattedDate: string;
    formattedDate = this.datePipe.transform(this.date.value._d, 'MMMM-yyyy') || '';

    let manager = '';
    let locationName = '';
    let reportDate = formattedDate;
    this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,false);
    const tableData = this.arrayList.map((emp:  { 
      empid: any;    
      empname: any;    
      approved_leaves: any;  
      lopcount: any ;
      total_leaves: any;   
    
    }, index: number) => [
     
        index + 1,
      emp.empid,
      emp.empname,
      emp.approved_leaves.slice(0, -1),
      emp.lopcount.slice(0, -1),
      emp.total_leaves.slice(0, -1),
    ]);
          autoTable(doc, {
            head: [['S. No.','Emp. ID','Emp. Name', 'Paid Leaves','LOP Leaves','Total']],
            body:tableData,
            startY: 40,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 12 }
         });
       doc.save('monthly_employee_leaves_report.pdf');
  } 
}
