import { Component, OnInit, ViewChild } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { AttendanceService } from 'src/app/modules/attendance/attendance.service';
import { LeavesService } from '../../leaves.service';
import { DatePipe } from '@angular/common';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { NgxSpinnerService } from 'ngx-spinner';
import { MatRadioChange } from '@angular/material/radio';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL'
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  }

}
@Component({
  selector: 'app-manager-optional-holiday-behalfemployee',
  templateUrl: './manager-optional-holiday-behalfemployee.component.html',
  styleUrls: ['./manager-optional-holiday-behalfemployee.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class ManagerOptionalHolidayBehalfemployeeComponent implements OnInit {

  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  searchControl = new FormControl('');
  dataList: any = [];
  pageLoading = true;
  optionalHolidayForm: any = UntypedFormGroup;
  searchForm!: UntypedFormGroup;
  employeeList: any = [];
  userSession: any;
  minFromDate!: Date;
  maxFromDate!: Date | null;
  minToDate!: Date | null;
  maxToDate!: Date;
  currentDate: Date = new Date();
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns = ['sno', 'applied_date', 'empcode', 'empname', 'location', 'holiday_date', 'holiday_name', 'status'];
  pipe = new DatePipe('en-US');

  workeddates: any;
  filteredEmp: any = [];
  btndisable: boolean = false;
  isNew: boolean = false;
  firstDayOfMonth = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth(), 1);
  constructor(
    private attendanceService: AttendanceService,
    private formBuilder: UntypedFormBuilder,
    private LM: LeavesService,
    public dialog: MatDialog,
    private router: Router,
    public datePipe: DatePipe,
    private spinner: NgxSpinnerService,
    private dialogService: ReusableDialogService
  ) {
    this.minFromDate = new Date('2020/01/01');;
    this.maxFromDate = new Date();
    this.minToDate = this.firstDayOfMonth;
    this.maxToDate = new Date();
  }
  holidayDate: any;
  holidayName: any;
  holidayId: any;
  validityStatus: any;
  approvedList: any = [];
  rejectedList: any = [];
  pendingStatus: boolean = false;
  approvedStatus: boolean = true;
  rejectedStatus: boolean = false;
  dataSearchControl = new FormControl('');

  ngOnInit(): void {
    this.optionalHolidayForm = this.formBuilder.group({
      empname: ['', Validators.required],
      optionalDate: ['', Validators.required],
      reason: [''],
    })
    this.searchForm = this.formBuilder.group({
      fromDate: [this.firstDayOfMonth],
      toDate: [new Date()]
    })
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getEmployeeListByManagerId();
    this.optionalHolidayForm.get('optionalDate')?.valueChanges.subscribe((selectedId: any) => {
      const selectedValue = this.workeddates.find((val: any) => val.holidayId === selectedId);
      this.holidayName = selectedValue ? selectedValue.holiday : '';
      this.holidayDate = selectedValue ? selectedValue.holidayDate : '';
      this.holidayId = selectedValue ? selectedValue.holidayId : '';

    });
    this.searchControl.valueChanges.subscribe((searchText: any) => {
      this.filterEmp(searchText);
    })
    this.searchData();
    this.searchForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      this.minToDate = selectedValue;
    });
  }

  getEmployeeListByManagerId() {
    this.attendanceService.getgetemployeesByMangerId(this.userSession.id).subscribe((res) => {
      if (res) {
        this.employeeList = res.data;
        this.filteredEmp = this.employeeList;
      }
    })
  }
  newRequest() {
    this.isNew = true;
  }

  getOptionalHolidaysList() {
    let empid = this.optionalHolidayForm.controls.empname.value;
    this.LM.getOptionalHolidayList(empid).subscribe((res: any) => {
      if (res.status) {
        this.workeddates = res.data;
      }
      this.optionalHolidayForm.controls.optionalDate.setValue('');
    })
  }

  save() {
    let data = {
      id: null,
      empid: this.optionalHolidayForm.controls.empname.value,
      holidayDate: this.holidayDate,
      remarks: this.optionalHolidayForm.controls.reason.value,
      userId: this.userSession.id,
      holidayId: this.holidayId,
      managerId: this.userSession.id,

    }
    this.btndisable = true;
    this.LM.setOptionalHoliday(data).subscribe((res: any) => {
      let val = res.data[0]
      if (res.status) {
        if (val.statusCode === 0) {
          this.dialogService.openDialog('Optional holiday request applied and approved successfully');
          this.cancel();

        } else if (val.statusCode === 1) {
          this.dialogService.openDialog('The optional holiday has already been applied for the selected date.');
          this.btndisable = false;

        } else if (val.statusCode == 4) {
          this.dialogService.openDialog('You have already applied for leave on this date. Please select another date');

        } else if (val.statusCode == 5) {
          this.dialogService.openDialog('You have already applied for attendance on this date. Please select another date');
        }
      } else {
        this.dialogService.openDialog('Unable to submit data');
        this.btndisable = false;
      }
    })

  }
  radioChange(event: MatRadioChange) {
    // if (event.value == 1) {
    //   // this.pendingStatus =true;
    //   this.approvedStatus =false;
    //   this.rejectedStatus =false;
    //   this.searchData();
    //   this.dataSearchControl.setValue('')

    //  } else
    if (event.value == 1) {
      // this.pendingStatus =false;
      this.approvedStatus = true;
      this.rejectedStatus = false;
      this.searchData();
      this.dataSearchControl.setValue('')

    } else if (event.value == 2) {
      // this.pendingStatus =false;
      this.approvedStatus = false;
      this.rejectedStatus = true;
      this.searchData();
      this.dataSearchControl.setValue('')
    }
  }
  searchData() {
    this.spinner.show();
    let payload = {
      fromdate: this.datePipe.transform(this.searchForm.controls.fromDate.value, "y-MM-dd"),
      todate: this.datePipe.transform(this.searchForm.controls.toDate.value, "y-MM-dd"),
      empid: null,
      managerid: this.userSession.id,
    }
    this.LM.getEmployeeUtilizedOptionalHoliday(payload).subscribe((res: any) => {
      if (res.status) {
        let list = res.data;
        this.dataList = [];
        this.approvedList = [];
        this.rejectedList = [];
        list.forEach((e: any) => {
          if (e.holidayStatus == "Approved") {
            this.approvedList.push(e);

          } else if (e.holidayStatus == "Rejected") {
            this.rejectedList.push(e);
          }
        })
        if (this.approvedStatus) {
          this.dataSource = new MatTableDataSource(this.approvedList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
          this.spinner.hide();

        } else {
          this.dataSource = new MatTableDataSource(this.rejectedList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
          this.spinner.hide();
        }
      } else {
        let list: any = [];
        this.dataSource = new MatTableDataSource(list);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
        this.spinner.hide();
      }
    })
  }

  submit() {
    if (this.btndisable) {
      return;
    }
    if (this.optionalHolidayForm.valid) {
      let empid = this.optionalHolidayForm.controls.empname.value
      this.LM.validateEmployeeOptionalHoliday(empid).subscribe((res: any) => {
        this.validityStatus = res.data[0].validityStatus;
        if (this.validityStatus == 0) {
          this.save();
        } else {
          this.dialogService.openDialog('You are reached optional holiday request limit');
          this.cancel();
        }
      })
    }
  }
  cancel() {
    this.router.navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/LeaveManagement/optional-holiday-behalf']));
  }
  clear() {
    this.searchForm.controls.fromDate.setValue(this.firstDayOfMonth);
    this.searchForm.controls.toDate.setValue(new Date());
    this.getEmployeeListByManagerId();
  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }


  filterEmp(searchText: any) {
    this.filteredEmp = this.employeeList.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase()) ||
      val.employee_code.toLowerCase().includes(searchText.toLowerCase())
    );
  }

  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage();
    }
  }
}
