import { Component, OnInit, ViewChild } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { AttendanceService } from 'src/app/modules/attendance/attendance.service';
import { LeavesService } from '../../leaves.service';
import { DatePipe } from '@angular/common';
import { MatDialog } from '@angular/material/dialog';
import { Router } from '@angular/router';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL'
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  }

}

@Component({
  selector: 'app-compoff-onbehalf',
  templateUrl: './compoff-onbehalf.component.html',
  styleUrls: ['./compoff-onbehalf.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class CompoffOnbehalfComponent implements OnInit {

  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  searchControl = new FormControl('');

  pageLoading = true;
  CompoffForm: any = UntypedFormGroup;
  employeeList: any = [];
  userSession: any;
  min: any;
  max: any;
  minLeave = new Date();
  maxLeave: any;
  myDateFilter: any;
  myDateFilterLeave: any;
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns = ['sno', 'empname', 'applied_date', 'worked_date', 'leave_date', 'status'];
  fromdate: any = [];
  holidays: any = [];
  pipe = new DatePipe('en-US');
  FromDatesHalfDays: any = [];
  fromDateFilter: any;
  leaveData: any;
  workeddates: any;
  filteredEmp: any = [];
  btndisable: boolean = false;
  constructor(
    private attendanceService: AttendanceService,
    private formBuilder: UntypedFormBuilder,
    private LM: LeavesService,
    public dialog: MatDialog,
    private router: Router,
    private dialogService:ReusableDialogService
  ) { }

  ngOnInit(): void {
    this.CompoffForm = this.formBuilder.group({
      empname: ['', Validators.required],
      workedDate: ['', Validators.required],
      leaveDate: ['', Validators.required],
      reason: ['', Validators.required]
    })
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.CompoffForm.get('workedDate')?.valueChanges.subscribe((selectedValue: any) => {
      this.getDaystobedisabledfromdate();
      if (selectedValue != '') {
        this.getCompOffValidityDuration(selectedValue);
      }
    });

    this.getEmployeeListByManagerId();
    this.getCompOffBehalfOfHistory();
    this.searchControl.valueChanges.subscribe((searchText: any) => {
      this.filterEmp(searchText)
    })

  }

  getEmployeeListByManagerId() {
    this.attendanceService.getgetemployeesByMangerId(this.userSession.id).subscribe((res) => {
      if (res) {
        this.employeeList = res.data;
        this.filteredEmp = this.employeeList;
      }
    })
  }

  getWorkedDatesForCompOffBehalfOf() {
    let empid = this.CompoffForm.controls.empname.value;
    this.LM.getWorkedDatesForCompOffBehalfOf(empid).subscribe((result: any) => {
      if (result) {
        this.workeddates = result.data;
      }
      this.CompoffForm.controls.workedDate.setValue('');
      this.CompoffForm.controls.leaveDate.setValue('');
    })
  }
  getCompOffBehalfOfHistory() {
    let manager_Id = this.userSession.id;
    this.LM.getCompOffBehalfOfHistory(manager_Id).subscribe((result: any) => {
      if (result.status) {
        this.dataSource = new MatTableDataSource(result.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading = false;
      }
    })

  }
  submit() {
    if (this.btndisable) {
      return;
    }
    if (this.CompoffForm.valid) {
      let data = {
        employeeid: this.CompoffForm.controls.empname.value,
        rmid: this.userSession.id,
        compoffworkeddate: this.CompoffForm.controls.workedDate.value,
        leavedate: this.pipe.transform(this.CompoffForm.controls.leaveDate.value, 'yyyy-MM-dd'),
      }
      this.btndisable = true;
      this.LM.setCompoffLeaveOnBehalfOfEmployee(data).subscribe((result: any) => {

        if (result.statevalue === 0) {
          this.dialogService.openDialog('Leave submitted successfully');
          this.navigationToCompOffonBehalfOff();
        } else if (result.statevalue === 1) {
          this.dialogService.openDialog('Record already exists');
          this.btndisable = false;
        } else {
          this.dialogService.openDialog('Unable to submit leave');
          this.btndisable = false;
        }
      })
    }
  }

  cancel() {
    this.navigationToCompOffonBehalfOff();
    // this.CompoffForm.reset();
    // this.CompoffForm.setErrors(null);
  }

  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  getDaystobedisabledfromdate() {

    let info = {
      employeeId: this.CompoffForm.controls.empname.value,
      leaveId: 9,
      workedDateValue: this.CompoffForm.controls.workedDate.value,
    }
    this.minLeave = new Date(info.workedDateValue)
    let minDateValue = new Date(info.workedDateValue);
    this.minLeave.setDate(minDateValue.getDate() + 1);

    this.LM.getDaysToBeDisabledForFromDateCompOff(info).then((result) => {
      if (result && result.status) {
        this.fromdate = result.data;
        for (var i = 0; i < result.data.length; i++) {
          (result.data[i].first_half && result.data[i].second_half) ? this.holidays.push(new Date(result.data[i].edate + ' ' + '00:00:00')) : this.FromDatesHalfDays.push(result.data[i]);
        }
        this.fromDateFilter = (d: Date): boolean => {
          let isValid = true;
          this.holidays.forEach((e: any) => {
            if (this.pipe.transform(e, 'yyyy/MM/dd') == this.pipe.transform(d, 'yyyy/MM/dd')) {
              isValid = false;
            }

          });
          return isValid;
        }
      }
    });

  }

  navigationToCompOffonBehalfOff() {
    this.router
      .navigateByUrl('/', { skipLocationChange: true })
      .then(() => this.router.navigate(['/LeaveManagement/compoff-onbehalf']));
  }
  getCompOffValidityDuration(date: any) {
    this.LM.getCompOffValidityDuration().subscribe((result: any) => {
      if (result.status) {
        this.maxLeave = '';
        var dates = new Date(date);
        this.minLeave = new Date(date);
        let minDateValue = new Date(date);
        this.minLeave.setDate(minDateValue.getDate() + 1);
        dates.setDate(dates.getDate() + Number(result.data[0].value));
        this.maxLeave = dates;
      }
    });
  }
  filterEmp(searchText: any) {
    this.filteredEmp = this.employeeList.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase()) ||
      val.employee_code.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmp.length <= 0) {
      this.searchControl.setValue('');
    }
  }

}
