import { Component,Inject, OnInit } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormGroup, Validators } from '@angular/forms';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { LeavesService } from '../../leaves.service';
import { Router } from '@angular/router';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { MatDialog, MatDialogRef,MAT_DIALOG_DATA } from '@angular/material/dialog';
import { DialogDetailComponent } from 'src/app/modules/reports/pages/dialog-detail/dialog-detail.component';


export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-optional-holiday-request',
  templateUrl: './optional-holiday-request.component.html',
  styleUrls: ['./optional-holiday-request.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})


export class OptionalHolidayRequestComponent implements OnInit {

  requestForm:any = UntypedFormGroup;
  displayForm:any = UntypedFormGroup;
  searchControl = new FormControl('');
  filteredOptionalHolidayList:any=[];
  btndisable:boolean = false;
  userSession:any;
  optionalHolidayList:any=[];
  validityStatus:any;
  view : boolean = false;

  constructor(
    private fb : FormBuilder,
    private LM: LeavesService,
    private router:Router,
    private dialog:MatDialog,
    public dialogRef: MatDialogRef<DialogDetailComponent>,
    @Inject(MAT_DIALOG_DATA) public data: any
  ) {
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');

   }

  ngOnInit(): void {
    this.requestForm = this.fb.group({
      optionalHoliday : ['',Validators.required],
      remarks : [''],
    })
    this.displayForm = this.fb.group({
      optionalHoliday : [''],
      remarks : [''],
    })
    this.view = this.data.isview
      this.validateEmployeeOptionalHoliday(); 
      this.getOptionalHolidayList();
      this.searchControl.valueChanges.subscribe((searchText: any) => {
        this.filterHolidays(searchText)
      })
      if(this.view){
        this.displayForm.controls.optionalHoliday.value = this.data.viewData.holidayId;
        this.displayForm.controls.remarks.value = this.data.viewData.reason;
      }
    


  }


  submit(){

    if(this.requestForm.valid){
      if(this.validityStatus == 0){
        let payload = {
          id: null,
          userId:this.userSession.id,
          holidayId : this.requestForm.controls.optionalHoliday.value,
          remarks: this.requestForm.controls.remarks.value,
          empid : this.userSession.id,
          managerId : null,
          holidayDate:this.getOptionalHolidayDate(this.requestForm.controls.optionalHoliday.value),
        }
        this.LM.setOptionalHoliday(payload).subscribe((res:any)=>{
       
          if(res.data[0].statusCode == 0){
              this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Optional Holiday submitted successfully.',
            });
            this.submitClose();
          }else if(res.data[0].statusCode == 1){
              this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Optional holiday already applied for the selected date.',
            });

          }else if(res.data[0].statusCode==4){
              this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'You have already applied for leave on this date. Please select another date.',
            });
          }else if(res.data[0].statusCode==5){
              this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'You have already applied for attendance on this date. Please select another date.',
            });
          }
        })
      }else{
          this.dialog.open(ReusableDialogComponent, {
          position: { top: `70px` },
          disableClose: true,
          data: 'Optional holiday limit is completed.',
        });
        this.cancel();
      }
    }
  }

  cancel(){
    this.dialogRef.close();
 
  }
  submitClose(){
    this.dialogRef.close('success');
  }
  getOptionalHolidayList(){
    let empid =this.userSession.id
   this.LM.getOptionalHolidayList(empid).subscribe((res:any)=>{ 
       this.optionalHolidayList = res.data;
       this.filteredOptionalHolidayList = this.optionalHolidayList
   })
 }

 validateEmployeeOptionalHoliday(){
  let  empid = this.userSession.id  
  this.LM.validateEmployeeOptionalHoliday(empid).subscribe((res:any)=>{  
  this.validityStatus = res.data[0].validityStatus
  })
}

filterHolidays(searchText: any) {
  this.filteredOptionalHolidayList = this.optionalHolidayList.filter((val: any) =>
    val.holiday.toLowerCase().includes(searchText.toLowerCase())
  );
}
getOptionalHolidayDate(id:any){
  let value;
  this.optionalHolidayList.forEach((item:any) =>{
    if(item.holidayId == id){
      value = item.holidayDate
    }
  })
  return value
}
}
