import { ReviewAndApprovalsComponent } from './../../dialog/review-and-approvals/review-and-approvals.component';
import { LeavesService } from './../../leaves.service';
import { ReusableDialogComponent } from 'src/app/pages/reusable-dialog/reusable-dialog.component';
import { Component, OnInit, ViewChild, ElementRef, Renderer2 } from '@angular/core';
import { MatTableDataSource } from '@angular/material/table';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { Router } from "@angular/router";
import { DatePipe } from '@angular/common';
import { MatDialog } from "@angular/material/dialog";
import { MatCalendarCellCssClasses } from '@angular/material/datepicker';
import { CalendarOptions, EventInput, FullCalendarComponent } from '@fullcalendar/angular'; // useful for typechecking
import { LoginService } from 'src/app/services/login.service';
// import { ChartOptions, ChartType } from 'chart.js';
// import { BaseChartDirective } from 'ng2-charts';
import { NgxSpinnerService } from 'ngx-spinner';
import { MatRadioChange } from '@angular/material/radio';
import { AdminService } from 'src/app/modules/admin/admin.service';


@Component({
  selector: 'app-user-dashboard',
  templateUrl: './user-dashboard.component.html',
  styleUrls: ['./user-dashboard.component.scss']
})
export class UserDashboardComponent implements OnInit {

  @ViewChild('calendar') calendarComponent!: FullCalendarComponent;
  initialEvents: EventInput[] = [];
  calendarApi: any;
  calendarOptions: CalendarOptions = {
    headerToolbar: {
      left: 'prev',
      center: 'title',
      right: 'next'
    },
    customButtons: {
      next: {

        click: this.nextMonth.bind(this),
      },
      prev: {
        click: this.prevMonth.bind(this),
      },

    },
    height: 380,
    initialView: 'dayGridMonth',
    weekends: true,
    editable: false,
    selectable: true,
    selectMirror: true,
    dayMaxEvents: true,
    dayMaxEventRows: true, // for the "more" link when too many events
    moreLinkContent: this.renderCustomMoreLink // function to render custom "more" link

  };
  renderCustomMoreLink(arg: any) {
    return {
      domNodes: [
        document.createTextNode(`+ ${arg.num}`)
      ]
    };
  }
  usersession: any;
  leavedata: any = [];
  leavebalance: any = [];
  holidaysList: any = [];
  holidaysListall: any = [];
  viewdata: any;
  allleaves: any = []
  deletedata: any;
  datesToBeHighlighted: any;
  titleName: any;
  reason: any;
  msgLM16: any;
  msgLM17: any;
  msgLM73: any;
  msgLM74: any;
  leavsemaster: any = []
  calenderleaves: any = [];
  arrayList: any = [];
  currentYear = new Date().getDate();
  myDateFilter: any;
  pipe = new DatePipe('en-US');
  today: any = new Date()
  isview: boolean = false;
  isdata: boolean = true;
  isholidays: boolean = false;
  maxall: number = 20;
  sampleElement: any;
  calendarCount: any = [];
  holidaysColumns: string[] = ['date', 'day', 'holiday'];
  holidaysColumns2: string[] = ['date', 'day', 'holiday', 'type'];
  displayedColumns: string[] = ['appliedon', 'leavetype', 'fromdate', 'todate', 'days', 'status', 'approver', 'action'];
  dataSource: MatTableDataSource<any> = <any>[];
  holidaydatasource: MatTableDataSource<any> = <any>[];
  holidaysalldatasource: MatTableDataSource<any> = <any>[];
  messageList: any = [];
  companyName: any;
  policyId: any;
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  leaveCycleYear: any;
  constructor(private router: Router, private LM: LeavesService, public datepipe: DatePipe, private ts: LoginService, public dialog: MatDialog, public spinner: NgxSpinnerService, private element: ElementRef, private renderer: Renderer2,
    private adminService: AdminService
  ) {
    this.companyName = sessionStorage.getItem('companyName');
  }
  publicHolidaysList: any = [];
  optionalHolidaysList: any = [];

  ngOnInit(): void {
    this.getLeaveCycleYear();
    this.getErrorMessages();
    this.usersession = JSON.parse(sessionStorage.getItem('user') || '');
    this.dataSource.paginator = this.paginator;
    this.getleavehistory(null, null);
    this.getLeaveBalance();
    this.getuserleavecalender();
  }

  getuserleavecalender() {
    // this.spinner.show();
    this.LM.getuserleavecalender(this.usersession.id).subscribe((result: any) => {
      // this.spinner.hide();

      this.calenderleaves = result.data;
      this.arrayList = result.data;
      this.arrayList.forEach((e: any) => {
        let item =
        {
          title: e.ltype,
          start: e.edate, ///new Date(e.attendancedate).toISOString().replace(/T.*$/, ''),
          // color:e.color,
          // color:e.color==null?'yellow':e.color,
          color: e.color,
          icon: 'fa-times-circle'

        }
        this.initialEvents.push(item);
      });
      this.calendarOptions.events = this.initialEvents;

      //this.calendarCountViewNoMore();
      // this.myDateFilter = (d: Date): boolean => {
      //   let isValid=false;
      // this.calenderleaves.forEach((e:any) => {
      //   if(this.pipe.transform(e.edate, 'yyyy/MM/dd') == this.pipe.transform(d, 'yyyy/MM/dd')){
      //     isValid=true

      //   }
      // });

      //   return isValid;
      // return (e.edate: Date): MatCalendarCellCssClasses => {
      //   if (date.getDate() === 1) {
      //     return 'special-date';
      //   } else {
      //     return 'special-date';
      //   }
      // };

      //  }

    })



  }

  // dateClass() {
  //   return (date: Date): MatCalendarCellCssClasses => {
  //     return this.calenderleaves.forEach((e: any) => {
  //       if (this.pipe.transform(e.edate, 'yyyy/MM/dd') == this.pipe.transform(date, 'yyyy/MM/dd')) {
  //         return 'special-date';
  //       }
  //       else {
  //         return date;
  //       }
  //     });

  //   };
  // }
  dateClass() {
    return (date: Date): MatCalendarCellCssClasses => {
      const highlightDate = this.calenderleaves
        .map((edate: any) => new Date(edate))
        .some(
          (d: any) =>
            d.getDate() === date.getDate() &&
            d.getMonth() === date.getMonth() &&
            d.getFullYear() === date.getFullYear()
        );

      return highlightDate ? 'special-date' : '';
    };
  }
  getleavehistory(page: any, size: any) {
    this.LM.getleavehistory(this.usersession.id, 1, 5).subscribe((result: any) => {
      this.allleaves = result;
      this.leavedata = result.data;
      this.dataSource = new MatTableDataSource(this.leavedata);


    })

  }

  getHolidaysList() {
    this.LM.getHolidays(this.leaveCycleYear, this.usersession.worklocation, 1,1, 20).subscribe((result) => {
      let data = result.data;
      if(data && data.length){
        for (let value of data) {
          (value.isOptionalHoliday == '1') ? this.optionalHolidaysList.push(value) : this.publicHolidaysList.push(value)
        };
      }      
      this.holidaydatasource = new MatTableDataSource(this.publicHolidaysList);
    })    
  }

  getLeaveBalance() {
    this.LM.getLeaveBalance(this.usersession.id).subscribe((result) => {
      if (result.status) {
        this.policyId = result.data[0][0].vpolicy_id;
        for (let i = 0; i < result.data[1].length; i++) {
          if (result.data[1][i].leavename === "Marriage Leave" && this.usersession.maritalstatus === "Single") {
            this.leavebalance.push(result.data[1][i])

          } else if (result.data[1][i].leavename === 'Maternity Leave' && this.usersession.maritalstatus === "Married") {
            if (this.usersession.gender === 'Female') {
              this.leavebalance.push(result.data[1][i])
            }
          } else if (result.data[1][i].leavename === 'Paternity Leave' && this.usersession.maritalstatus === "Married") {
            if (this.usersession.gender === 'Male') {
              this.leavebalance.push(result.data[1][i])
            }
          } else if (result.data[1][i].leavename !== 'Paternity Leave' && result.data[1][i].leavename !== "Marriage Leave" && result.data[1][i].leavename !== 'Maternity Leave') {
            this.leavebalance.push(result.data[1][i])
          }
          // for(let t =0; t<result.data[0].length; t++){
          //   if(this.usersession.maritalstatus === "Married" && result.data[0][t].leavename === "Marriage Leave"){
          //     result.data[0].splice(t,1);
          //     if(this.usersession.gender === 'Male' && result.data[0][t].leavename === 'Maternity Leave'){
          //       result.data[0].splice(t,1);
          //     }else if(this.usersession.gender === "FeMale" && result.data[0][t].leavename === 'Paternity Leave') {
          //       result.data[0].splice(t,1);
          //     }
          //   }else {
          //     if(result.data[0][t].leavename === 'Maternity Leave' || result.data[0][t].leavename === 'Paternity Leave'){
          //       result.data[0].splice(t,1)
          //     }

          //   }
        }

      }
    })
  }

  onSelect(event: any) {
    this.today = event;
  }

  view(data: any) {
    this.isview = true;
    this.isdata = false;
    this.viewdata = data;
  }

  getLeaveCycleYear() {
    this.LM.getLeaveCycleYear().subscribe((result) => {
      this.leaveCycleYear = result.data.leave_cycle_year;
      this.getHolidaysList();
    })
  }

  viewall() {
    this.LM.getHolidays(this.leaveCycleYear, this.usersession.worklocation,0, 1, 1000).subscribe((result) => {
      let data = result.data;
      this.holidaysListall = data;
      this.holidaysalldatasource = new MatTableDataSource(this.holidaysListall);
    })
    this.isdata = false;
    this.isholidays = true;
  }
  close() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/LeaveManagement/UserDashboard"]));
  }

  cancel(data: any) {
    this.deletedata = data;
    this.titleName = "Do you really want to cancel the leave?"
    this.openDialogcancel();
  }
  openDialogcancel(): void {
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '500px', position: { top: `100px` },
      data: { name: this.titleName, reason: this.reason }
    });

    dialogRef.afterClosed().subscribe(result => {
      this.deletedata.actionreason = result.reason;
      if (result != '') {
        this.LM.cancelLeaveRequest(this.deletedata).subscribe((data) => {
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/LeaveManagement/UserDashboard"]));
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Leave request cancelled successfully.'
            });

          }
          else {
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Unable to cancel leave request.'
            });
          }
        })
      }
    });
  }

  delete(data: any) {
    this.deletedata = data;
    this.titleName = "Do you really want to delete the leave?"
    this.openDialogdelete();
  }
  openDialogdelete(): void {
    const dialogRef = this.dialog.open(ReviewAndApprovalsComponent, {
      width: '500px', position: { top: `100px` },
      data: { name: this.titleName, reason: this.reason }
    });

    dialogRef.afterClosed().subscribe(result => {
      this.deletedata.actionreason = result.reason;
      if (result != '') {
        this.LM.setDeleteLeaveRequest(this.deletedata).subscribe((data) => {
          if (data.status) {
            this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
              this.router.navigate(["/LeaveManagement/UserDashboard"]));
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Leaverequest deleted successfully.'
            });

          }
          else {
            let dialogRef = this.dialog.open(ReusableDialogComponent, {
              position: { top: `70px` },
              disableClose: true,
              data: 'Unable to delete leaverequest.'
            });
          }
        })
      }
    });
  }
  nextMonth(): void {
    this.calendarApi = this.calendarComponent.getApi();
    this.calendarApi.next();
  }
  prevMonth(): void {
    this.calendarApi = this.calendarComponent.getApi();
    this.calendarApi.prev();
  }
  currentMonth(): void {
    this.calendarApi = this.calendarComponent.getApi();
    this.calendarApi.today();
  }

  edit(leave: any) {
    leave.URL = '/LeaveManagement/UserDashboard';
    this.router.navigate(['/LeaveManagement/LeaveRequest'], { state: { leaveData: leave } });
  }

  getErrorMessages() {
    let payload = {
      "code": null,
      "pagenumber": 1,
      "pagesize": 100,
      "companyName": this.companyName,
    }
    this.adminService.getErrorMessagesforLeave(payload).subscribe((result: any) => {
      if (result.status) {
        this.messageList = result.data;

        this.messageList.forEach((element: any) => {

          if (element.errorcode == 'LM16') {
            this.msgLM16 = element.errormessage;
          }
          else if (element.errorcode == 'LM17') {
            this.msgLM17 = element.errormessage;
          }
          else if (element.errorcode == 'LM73') {
            this.msgLM73 = element.errormessage;
          }
          else if (element.errorcode == 'LM74') {
            this.msgLM74 = element.errormessage;
          }

        })
      }

    })
  }
  calendarCountViewNoMore() {
    setTimeout(() => {

      this.sampleElement = (<HTMLElement>this.element.nativeElement).querySelectorAll('.fc-daygrid-more-link');
      var closeElement = (<HTMLElement>this.element.nativeElement).querySelectorAll('.fc-daygrid-more-link.fc-more-link');
      for (var j = 0; j < this.sampleElement.length; j++) {
        this.calendarCount[j] = this.sampleElement[j].innerHTML.substring(0, this.sampleElement[j].innerHTML.length - 4)
        this.sampleElement[j].innerHTML = this.calendarCount[j];
      }
      for (var k = 0; k < closeElement.length; k++) {
        if (closeElement[k] != null) {
          this.renderer.listen(closeElement[k], 'click', () => {
            this.closePopUpOver();
          });
        }
      }

    }, 1000);
  }
  closePopUpOver() {
    var openElement = (<HTMLElement>this.element.nativeElement).querySelectorAll('.fc-popover-close.fc-icon.fc-icon-x');
    setTimeout(() => {
      for (var k = 0; k < openElement.length; k++) {
        this.renderer.listen(openElement[k], 'click', () => {
          this.sampleElement = (<HTMLElement>this.element.nativeElement).querySelectorAll('.fc-daygrid-more-link');
          for (var j = 0; j < this.sampleElement.length; j++) {
            this.sampleElement[j].innerHTML = this.calendarCount[j];
          }
        });
      }
    }, 500);
  }

  radioChange(event: MatRadioChange) {
    if (event.value == 1) {

      this.holidaydatasource = new MatTableDataSource(this.publicHolidaysList);

    } else if (event.value == 2) {
      this.holidaydatasource = new MatTableDataSource(this.optionalHolidaysList);
    }
  }
}


