import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { FormControl, UntypedFormBuilder, UntypedFormControl, UntypedFormGroup, Validators } from "@angular/forms";
import { DatePipe } from "@angular/common";
import { MatPaginator } from "@angular/material/paginator";
import { MatSort } from "@angular/material/sort";
import { Router } from '@angular/router';
import { MatTableDataSource } from "@angular/material/table";
import * as XLSX from "xlsx";
import { NgxSpinnerService } from 'ngx-spinner';
import { LeavesService } from '../../leaves.service';
import { ReportsService } from 'src/app/modules/reports/reports.service';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MatDatepicker } from '@angular/material/datepicker';
import { Moment } from 'moment';
import * as _moment from 'moment';
import * as pdfMake from "pdfmake/build/pdfmake";
import * as pdfFonts from "pdfmake/build/vfs_fonts";
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';
// import {default as _rollupMoment} from 'moment';
const moment = _moment;
(pdfMake as any).vfs = (pdfFonts as any).pdfMake?.vfs;
const htmlToPdfmake = require("html-to-pdfmake");
/**test */
export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};


@Component({
  selector: 'app-emp-payroll-report',
  templateUrl: './emp-payroll-report.component.html',
  styleUrls: ['./emp-payroll-report.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class EmpPayrollReportComponent implements OnInit {
  viewdata: any
  date = new UntypedFormControl(moment());
  setMonthAndYear(normalizedMonthAndYear: Moment, datepicker: MatDatepicker<Moment>) {
    const ctrlValue = this.date.value!;
    ctrlValue.month(normalizedMonthAndYear.month());
    ctrlValue.year(normalizedMonthAndYear.year());
    this.date.setValue(ctrlValue);
    datepicker.close();
    this.viewdata = ctrlValue._d;
  }
  searchForm!: UntypedFormGroup;
  displayedColumns: string[] = ['sno', 'empid', 'empname', 'totalleavebalance', 'lossofpay', 'totalleaves'];
  dataSource: MatTableDataSource<any> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  arrayList: any = [];
  minDate: any;
  pipe = new DatePipe('en-US');
  userSession: any;
  employeeDetails: any;
  year: any;
  max = new Date()
  months = [{ id: 0, month: 'Jan' }, { id: 1, month: 'Feb' }, { id: 2, month: 'Mar' }, { id: 3, month: 'Apr' }, { id: 4, month: 'May' }, { id: 5, month: 'Jun' }, { id: 6, month: 'Jul' }, { id: 7, month: 'Aug' }, { id: 8, month: 'Sep' }, { id: 9, month: 'Oct' }, { id: 10, month: 'Nov' }, { id: 11, month: 'Dec' }]
  monthdata: any;
  filteredEmp: any = [];
  searchControlForEmp = new FormControl('');

  constructor(private LM: LeavesService, private router: Router, public formBuilder: UntypedFormBuilder, 
    public spinner: NgxSpinnerService, private RS: ReportsService,
    private pdfService: PdfHeaderService,) { }
  @ViewChild('table') table!: ElementRef;

  ngOnInit(): void {
    this.getallEmployeesList();

    this.searchForm = this.formBuilder.group({
      fromDate: ['', Validators.required],
      employeeId: ['All'],
      toDate: ['', Validators.required],
    });
    this.searchForm.get('fromDate')?.valueChanges.subscribe((selectedValue: any) => {
      this.minDate = selectedValue;
    });
    // this.Searchform();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.dataSource = new MatTableDataSource(this.arrayList);
    this.searchControlForEmp.valueChanges.subscribe(searchText => {
      this.filterEmp(searchText);
    });
  }
  exportAsXLSX() {

    this.year = this.viewdata != undefined ? this.viewdata.getFullYear() : new Date().getFullYear();
    const exportData = this.arrayList.map((row:any, index:any) => ({
      "S.No": index + 1,
      "Emp.Id":row.empid,
      "Emp. Name": row.empname,
      "Loss of Pay Count": row.lopcount.slice(0,-1),
      "Absents": row.absents.slice(0,-1),
      "Leaves Approved": row.approved_leaves.slice(0,-1),
    }));
  
    const ws: XLSX.WorkSheet = XLSX.utils.json_to_sheet(exportData);
  
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Payroll_Report');
  
    /* save to file */
    XLSX.writeFile(wb,  this.year + " - " + 'Payroll_Report.xlsx');
  
  }

  getallEmployeesList() {
    this.RS.getTotalEmployeslist().subscribe((res: any) => {
      if (res.status && res.data.length > 0) {
        this.employeeDetails = res.data;
        this.filteredEmp = this.employeeDetails;
      }

    })
  }
  Searchform() {
    if (this.searchForm.valid) {


      let data = {
        empid: this.searchForm.controls.employeeId.value == "All" ? null : this.searchForm.controls.employeeId.value,
        fromDate: this.pipe.transform(this.searchForm.controls.fromDate.value, 'yyyy-MM-dd'),
        toDate: this.pipe.transform(this.searchForm.controls.toDate.value, 'yyyy-MM-dd')
      }
    
      this.spinner.show();
      this.LM.getReportForPayrollProcessing(data).subscribe((res: any) => {
        this.spinner.hide();

        this.arrayList = []
        if (res.status && res.data.length > 0) {
          this.arrayList = res.data;
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.paginator.pageSize = 5;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
        }
        else {
          this.arrayList = [];
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.paginator.pageSize = 5;
          this.dataSource.sort = this.sort;
        }
      })
    }
  }
  resetform() {
    this.router.navigateByUrl('/', { skipLocationChange: true }).then(() =>
      this.router.navigate(["/LeaveManagement/payrollreport"]));
  }
  getPageSizes(): number[] {

    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  filterEmp(searchText: any) {

    this.filteredEmp = this.employeeDetails.filter((val: any) =>
      val.emp_name.toLowerCase().includes(searchText.toLowerCase()) || 
      val.empid.toLowerCase().includes(searchText.toLowerCase())
    );
    if (this.filteredEmp.length <= 0) {
      this.searchControlForEmp.setValue('');
    }
  }

  generatePDF() {
  
    const doc = new jsPDF();
    const reportName = 'Monthly Payroll Report';
    let fromdate = (this.pipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY"));
    let todate = (this.pipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY"));

    let manager = '';
    let locationName = '';
    let reportDate = fromdate +' to '+ todate;
    const headerHeight = 33;
    const tableData = this.arrayList.map((emp:  { empid:any; empname: any;    lopcount: any;   absents: any ;
                                                  approved_leaves: any}, index: number) => [
      index + 1,
      emp.empid,
      emp.empname,
      emp.lopcount.slice(0,-1),
      emp.absents.slice(0,-1),
      emp.approved_leaves.slice(0,-1),
    ]);
          autoTable(doc, {
            head: [['S.No.','Emp. ID','Emp. Name', 'Loss of Pay Count','Absents','Leaves Approved']],
            body:tableData,
            startY: headerHeight,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 11},
            margin: { top: headerHeight },
            didDrawPage: (data) => {
              this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,false);
              doc.setFontSize(10);
              doc.setTextColor(40);
            }
         });
       doc.save('Monthly_Payroll_Report.pdf');
  } 
}
