  SummaryReportForm: any = UntypedFormGroup;
  locationIshide: boolean = false;
  worklocationDetails: any[] = [];
  locationIschecked: boolean = false;
  mgrIshide: boolean = false;
  mgrIschecked: boolean = false;
  selectedManagers: any = [];
  managersDetails: any[] = [];
  userSession: any;
  employeelist: any;
  date = new Date();
  selectedLocations: any = [];
  searchControlforLoc = new FormControl('');
  searchControlforRM = new FormControl('');
  filteredLocations: any = [];
  filteredManagers: any = [];
  allManagers: boolean = false;
  allLocations: boolean = false;


  companyName: any;
  filter = new UntypedFormControl();
  obj: any;
  dateDayArray: any = [];
  List: any[] = [
  ];
  headersList: any = [];
  dataSource: MatTableDataSource<any> = <any>[];
  displayedColumns: string[] = ['sno', 'empname', 'details', 'leave_type', 'applied_date', 'from_date',
    'to_date', 'leave_count', 'leave_status'];
  isLoading = false;
  pageLoading = true;
  minDate = new Date('1950/01/01');
  maxDate = new Date();
  minToDate: any;



  @ViewChild('table') table!: ElementRef;
  @ViewChild(MatPaginator) paginator!: MatPaginator;
  @ViewChild(MatSort) sorter!: MatSort;
