import { Component, Inject, OnInit } from '@angular/core';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { ReportsService } from 'src/app/modules/reports/reports.service';


@Component({
  selector: 'app-month-wise-leaves-dialog',
  templateUrl: './month-wise-leaves-dialog.component.html',
  styleUrls: ['./month-wise-leaves-dialog.component.scss']
})
export class MonthWiseLeavesDialogComponent implements OnInit {
  displayedColumns: string[] = ['sno', 'shift', 'employee'];
  dataSource: any = [];
  date: any;
  rmId: any;
  constructor(public dialogRef: MatDialogRef<MonthWiseLeavesDialogComponent>,
    private reportService: ReportsService,
    @Inject(MAT_DIALOG_DATA) public data: any) { 
    this.date = data.date_value;
    this.rmId = data.rm_id_value;
    }
  employeesList: any = [];
  ngOnInit(): void {
    this.viewData();
  }

  viewData() {
    let dateValue = this.date.split("-").reverse().join("-");
    this.employeesList = [];
     let data = {
      "rm_id_value":2,
      "date_value":'2024-07-30'
     }
    this.reportService.getShiftsEmployeesDetailReportByDate(data).subscribe((res) => {
      if (res.status) {
        this.employeesList = res.data;
        this.dataSource = this.employeesList;
         } else {
           this.employeesList = [];
         }
    })
  }
}

