import { Component, OnInit, TemplateRef, ViewChild } from '@angular/core';
import { FormBuilder, FormControl, UntypedFormGroup } from '@angular/forms';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { UserData } from 'src/app/modules/attendance/models/EmployeeData';
import { LeavesService } from '../../leaves.service';
import { Router } from '@angular/router';
import { MatDatepickerInputEvent } from '@angular/material/datepicker';
import { DateAdapter, MAT_DATE_FORMATS, MAT_DATE_LOCALE } from '@angular/material/core';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import { DatePipe } from '@angular/common';
import { MatDialog } from '@angular/material/dialog';
import { OptionalHolidayRequestComponent } from 'src/app/modules/leaves/dialog/optional-holiday-request/optional-holiday-request.component';
import { ReusableDialogService } from 'src/app/services/reusable-dialog.service';

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-employee-optional-holiday-request',
  templateUrl: './employee-optional-holiday-request.component.html',
  styleUrls: ['./employee-optional-holiday-request.component.scss'],
  providers: [
    { provide: DateAdapter, useClass: MomentDateAdapter, deps: [MAT_DATE_LOCALE] },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class EmployeeOptionalHolidayRequestComponent implements OnInit {

  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  @ViewChild('dialogTemplate') dialogTemplate!: TemplateRef<any>;
  
  // requestForm:any = UntypedFormGroup;
  tableform:any=UntypedFormGroup;
  optionalHolidayList:any=[];
  pageLoading=true;
  displayedColumns: string[] = ['sno','appliedOn','holidayDate','holidayName','status','action'];
  btndisable:boolean=false;
  userSession:any;
  dataSource: MatTableDataSource<UserData>=<any>[];
  applyOptionalHoliday:boolean = false;
  displayOptionalHolidayUtilizedList:boolean = true;
  minFromDate: Date ;
  maxFromDate: Date | null ;
  minToDate: Date | null ;
  maxToDate: Date ;
  currentDate: Date = new Date();
  searchControl = new FormControl('');
  filteredOptionalHolidayList:any=[];
  validityStatus:any;
  remarksView:any;
  firstDayOfMonth = new Date(this.currentDate.getFullYear(), this.currentDate.getMonth(), 1);

  constructor( 
    private fb : FormBuilder,
    private LM: LeavesService,
    private router:Router,
    public datePipe: DatePipe,
    private dialog:MatDialog,
    private dialogService:ReusableDialogService

  ) { 
    this.minFromDate = new Date();
    this.minFromDate.setDate(this.currentDate.getDate() - 90);
    this.maxFromDate = new Date();
    this.minToDate = this.firstDayOfMonth;
    this.maxToDate = new Date();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
   

    // this.requestForm = this.fb.group({
    //   optionalHoliday : ['',Validators.required],
    //   remarks : [''],
    // })
  }

  ngOnInit(): void {
    
    this.tableform = this.fb.group({
      fromDate: [this.firstDayOfMonth],
      toDate: [new Date()]
    })
    this.getEmployeeUtilizedOptionalHoliday();
    // this.searchControl.valueChanges.subscribe((searchText: any) => {
    //   this.filterHolidays(searchText)
    // })
  }

  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  cancel(){
    this.router
    .navigateByUrl('/', { skipLocationChange: true })
    .then(() => this.router.navigate(['/LeaveManagement/optional-holiday-request']));
  }

  
  getEmployeeUtilizedOptionalHoliday(){
    let payload = {
      fromdate:this.datePipe.transform(this.tableform.controls.fromDate.value, "y-MM-dd"),
      todate : this.datePipe.transform(this.tableform.controls.toDate.value, "y-MM-dd"),
      empid:this.userSession.id,
      managerid:null,
    }
    this.LM.getEmployeeUtilizedOptionalHoliday(payload).subscribe((res:any)=>{
      if(res.status){
        this.dataSource = new MatTableDataSource(res.data);
        this.dataSource.paginator = this.paginator;
        this.dataSource.sort = this.sort;
        this.pageLoading=false;
      }
    })
  }

  

  fromDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.minToDate = event.value;
    if (event.value !== null) {
      this.maxToDate = new Date(
        // event!.value.getFullYear(),
        // event!.value.getMonth(),
        // event!.value.getDate() + 30
      );
    }
    // this.tableform.controls.toDate.setValue('')
  }

  toDateChange(type: string, event: MatDatepickerInputEvent<Date>) {
    this.maxFromDate = event.value;
    // if (event.value !== null) {
    //   this.minFromDate = new Date(
    //     event!.value.getFullYear(),
    //     event!.value.getMonth(),
    //     event!.value.getDate() - 30
    //   );
    // }
    
  }

  
  getOptionalHolidayDate(id:any){
    let value;
    this.optionalHolidayList.forEach((item:any) =>{
      if(item.holidayId == id){
        value = item.holidayDate
      }
    })
    return value
  }

  deleteOptionalHoliday(event:any){
    
    let payload = {
        id: event.optionalHolidayId,
        userId:this.userSession.id,
        holidayId : event.holidayId,
        remarks: event.reason,
        empid : this.userSession.id,
        managerId : null,
        holidayDate:this.datePipe.transform(event.holidayDate,'yyyy-MM-dd'),
      }

      this.LM.setOptionalHoliday(payload).subscribe((res:any)=>{
        if(res.status){
          if(res.data[0].statusCode == 3){
            this.dialogService.openDialog('Optional Holiday request deleted successfully.');
            this.cancel();
          }
        }
      })
  }


  applyFilter(event: Event) {
    const filterValue = (event.target as HTMLInputElement).value;
    this.dataSource.filter = filterValue.trim().toLowerCase();
    if (this.dataSource.paginator) {
      this.dataSource.paginator.firstPage()
    }
  }

  requestView(data:any){
    this.remarksView = data.actionReason;
    const dialogData = data.actionReason;
    this.dialog.open(this.dialogTemplate, {
      data: dialogData,
    });
  }

  resetform(){
    this.tableform.controls.fromDate.setValue(this.firstDayOfMonth);
    this.tableform.controls.toDate.setValue(new Date());
    this.getEmployeeUtilizedOptionalHoliday();
  }

  openDialog(): void {
    const dialogRef = this.dialog.open(OptionalHolidayRequestComponent, {
      width: '500px', position: { top: `70px` },
      data:{ isview: false}
      
    });
    dialogRef.afterClosed().subscribe(result => {
      if (result != undefined) {
        if (result == 'success') {
          this.getEmployeeUtilizedOptionalHoliday();
        }
      }
      
    });
  }
  
  requestViewRemarks(event:any){
    const dialogRef = this.dialog.open(OptionalHolidayRequestComponent, {
      width: '500px', position: { top: `70px` },
      data: {viewData: event, isview: true} ,
      
    });
    dialogRef.afterClosed().subscribe(result => {
      
    });
  }
}
