    this.isBereavement = event.is_b === 1 ? true : false
    this.isCompOffLeave = event.is_comp === 1 ? true : false
    this.isEvent = event.is_event === 1 ? true : false
    this.isSickLeave = event.is_sick_leave === 1 ? true : false
