import { Component, OnInit } from '@angular/core';
import { LeavesService } from "../../leaves.service";
import { UntypedFormControl } from '@angular/forms';

@Component({
  selector: 'app-manager-dashboard',
  templateUrl: './manager-dashboard.component.html',
  styleUrls: ['./manager-dashboard.component.scss'],
})
export class ManagerDashboardComponent implements OnInit {
  compoff: any;
  isLeaveModuleActive: any = true;
  userSession: any;
  constructor(private LM: LeavesService) { }
  selectedtab = new UntypedFormControl(0);
  leaveCancelPendingCount: any;
  leaveRequestpendingCount: any;
  compoffPendingCount: any;
  ngOnInit(): void {
    this.getCompoffleavestatus();
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    var jsonString = sessionStorage.getItem('activeModule');
    if (jsonString && jsonString.toString().length > 0) {
      var activeModule: any = JSON.parse(jsonString);
      if (activeModule.module.modulename.toString().trim().toLowerCase().includes('leave')) {
        this.isLeaveModuleActive = true;
      }
      else this.isLeaveModuleActive = false;
    }
    this.getCompoffForApprovals();
    this.getLeavesForCancellation();
    this.getLeavesForApprovals();
  }

  getCompoffleavestatus() {
    this.LM.getCompoffleavestatus().subscribe((result) => {
      if (result.status) {
        this.compoff = result.data.compoff_status;
      }
    })
  }

  selectedTabChange(event: any) {
    if (event.index == 0) {
      this.selectedtab.setValue(0);
    } else if (event.index == 1) {
      this.selectedtab.setValue(1);
    } else if (event.index == 2) {
      this.selectedtab.setValue(2);
    } else if (event.index == 3) {
      this.selectedtab.setValue(3);
    } else if (event.index == 4) {
      this.selectedtab.setValue(4);
    }
  }

  getLeavesForCancellation() {
    let arrayList = [];
    this.LM.getLeavesForCancellation(this.userSession.id).subscribe((res: any) => {
      arrayList = res.data;
      if (res.status && arrayList.length > 0) {
        this.leaveCancelPendingCount = arrayList.length;

      } else {
        this.leaveCancelPendingCount = arrayList.length
      }
    })
  }

  getCompoffForApprovals() {
    let arrayList = [];
    this.LM.getCompoffForApprovals(this.userSession.id).subscribe((res: any) => {
      arrayList = res.data;
      if (res.status && arrayList.length > 0) {
        this.compoffPendingCount = arrayList.length;
      } else {
        this.compoffPendingCount = arrayList.length;
      }
    });
  }

    getLeavesForApprovals(){
      let arrayList = [];
      this.LM.getLeavesForApprovals(this.userSession.id).subscribe((res: any) => {
        arrayList = res.data;
        if (res.status && arrayList.length > 0) {
          this.leaveRequestpendingCount = arrayList.length;
        } else {
          this.leaveRequestpendingCount = arrayList.length;
        }

      })
    }
    updatePendingRequestCount(count: number) {
      this.leaveRequestpendingCount = count;
    }
    updatePendingCompoffCount(count: number) {
      this.compoffPendingCount = count;
    }
    updatePendingCancelCount(count: number) {
      this.leaveCancelPendingCount = count;
    }
}
