import { Component, OnInit, ViewChild, ElementRef } from '@angular/core';
import { LeavesService } from '../../leaves.service';
import {
  UntypedFormBuilder,
  FormControl,
  UntypedFormGroup,
} from '@angular/forms';
import { DatePipe } from '@angular/common';
import { MatPaginator } from '@angular/material/paginator';
import { MatSort } from '@angular/material/sort';
import { MatTableDataSource } from '@angular/material/table';
import { UserData } from '../../../attendance/models/EmployeeData';
import * as XLSX from 'xlsx';
import { NgxSpinnerService } from 'ngx-spinner';
import { MomentDateAdapter } from '@angular/material-moment-adapter';
import {
  DateAdapter,
  MAT_DATE_FORMATS,
  MAT_DATE_LOCALE,
} from '@angular/material/core';

import * as _moment from 'moment';
import * as pdfMake from 'pdfmake/build/pdfmake';
import * as pdfFonts from 'pdfmake/build/vfs_fonts';
import { ReportsService } from 'src/app/modules/reports/reports.service';
// import {default as _rollupMoment} from 'moment';
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';
import { PdfHeaderService } from 'src/app/services/pdf-header-service/pdf-header.service';

const moment = _moment;
(pdfMake as any).vfs = (pdfFonts as any).pdfMake?.vfs;
const htmlToPdfmake = require('html-to-pdfmake');

export const MY_FORMATS = {
  parse: {
    dateInput: 'LL',
  },
  display: {
    dateInput: 'DD-MM-YYYY',
    monthYearLabel: 'YYYY',
    dateA11yLabel: 'LL',
    monthYearA11yLabel: 'YYYY',
  },
};

@Component({
  selector: 'app-detailed-report-for-manager',
  templateUrl: './detailed-report-for-manager.component.html',
  styleUrls: ['./detailed-report-for-manager.component.scss'],
  providers: [
    {
      provide: DateAdapter,
      useClass: MomentDateAdapter,
      deps: [MAT_DATE_LOCALE],
    },

    { provide: MAT_DATE_FORMATS, useValue: MY_FORMATS },
  ],
})
export class DetailedReportForManagerComponent implements OnInit {
  constructor(
    private LM: LeavesService,
    public formBuilder: UntypedFormBuilder,
    public spinner: NgxSpinnerService,
    public reportsService: ReportsService,
    private pdfService: PdfHeaderService,
    public datePipe: DatePipe,
  ) {
    this.companyDBName = sessionStorage.getItem('companyName');
    // var date = new Date();
    // // date.setDate(date.getDate()-7)
  }
  @ViewChild('table') table!: ElementRef;
  searchForm!: UntypedFormGroup;
  displayedColumns: string[] = [
    'sno',
    'employeeName',
    'employeeId',
    'leaveType',
    'designation',
    'appliedDate',
    'startDate',
    'toDate',
    'noOfDays',
    'status',
    'approvedBy',
  ];
  dataSource: MatTableDataSource<UserData> = <any>[];
  @ViewChild(MatPaginator)
  paginator!: MatPaginator;
  @ViewChild(MatSort)
  sort!: MatSort;
  pageLoading = true;
  searchControlForEmp = new FormControl('');
  searchControlForLeaveType = new FormControl('');
  searchControlForDesignation = new FormControl('');
  arrayList: any = [];
  userSession: any;
  leaveTypes: any = [];
  ishide: boolean = true;
  onchangeflag: boolean = false;
  // leaveStatus:any=[];
  designations: any = [];
  employeeDetails: any = [];
  page = 1;
  count = 0;
  tableSize = 5;
  tableSizes = [5, 25, 50, 'All'];
  pipe = new DatePipe('en-US');
  companyDBName: any;
  filteredEmp: any = [];
  filteredLeaveTypes: any = [];
  filteredDesignations: any = [];
  onTableDataChange(event: any) {
    this.onchangeflag = true;
    this.page = event;
    this.Searchform();
    // this.getHolidays(this.year?this.year:null,this.locationId?this.locationId:null);
  }
  onTableSizeChange(event: any) {
    this.tableSize = event.target.value;
    this.onchangeflag = true;
    this.page = 1;
    this.Searchform();

    // this.getHolidays(this.year?this.year:null,this.locationId?this.locationId:null);
  }
  minFromDate: any;
  isCustom: boolean = false;
  ngOnInit(): void {
    this.isCustom = false;
    this.searchForm = this.formBuilder.group({
      leaveType: ['All'],
      leaveStatus: ['All'],
      designation: ['All'],
      fromDate: [new Date()],
      toDate: [new Date()],
      DateFormate: ['currentWeek'],
      employeeId: ['All'],
    });
    this.userSession = JSON.parse(sessionStorage.getItem('user') || '');
    this.getLeaveTypes();
    this.getDesignation();
    this.getEmployeesForReportingManager();

    const today = new Date();
    let fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
    let toDate = new Date(today.setDate(today.getDate() - today.getDay()));
    this.searchForm.controls.fromDate.setValue(fromdate);
    this.searchForm.controls.toDate.setValue(
      new Date(toDate.setDate(toDate.getDate() + 6))
    );

    this.searchForm
      .get('DateFormate')
      ?.valueChanges.subscribe((selectedValue: any) => {
        switch (selectedValue) {
          case 'currentWeek':
            var fromdate = new Date(today.setDate(today.getDate() - today.getDay()));
            this.searchForm.controls.fromDate.setValue(new Date(today.setDate(today.getDate() - today.getDay())));
            this.searchForm.controls.toDate.setValue(new Date(fromdate.setDate(fromdate.getDate() + 6)));
            this.isCustom = false;
            break;
          case 'lastWeek':
            var fromdate = new Date(
              today.setDate(today.getDate() - today.getDay())
            );
            this.searchForm.controls.fromDate.setValue(
              new Date(fromdate.setDate(fromdate.getDate() - 7))
            );
            this.searchForm.controls.toDate.setValue(
              new Date(fromdate.setDate(fromdate.getDate() + 6))
            );
            this.isCustom = false;
            break;
          case 'currentMonth':
            this.searchForm.controls.fromDate.setValue(
              new Date(today.getFullYear(), today.getMonth(), 1)
            );
            this.searchForm.controls.toDate.setValue(new Date());
            this.isCustom = false;
            break;
          case 'lastMonth':
            this.searchForm.controls.fromDate.setValue(
              new Date(today.getFullYear(), today.getMonth() - 1)
            );
            this.searchForm.controls.toDate.setValue(
              new Date(today.getFullYear(), today.getMonth(), 0)
            );
            this.isCustom = false;
            break;
          case 'quaterOne':
            this.searchForm.controls.fromDate.setValue(
              new Date('01-01-' + today.getFullYear().toString())
            );
            this.searchForm.controls.toDate.setValue(
              new Date('03-31-' + today.getFullYear().toString())
            );
            this.isCustom = false;
            break;
          case 'quaterTwo':
            this.searchForm.controls.fromDate.setValue(
              new Date('04-01-' + today.getFullYear().toString())
            );
            this.searchForm.controls.toDate.setValue(
              new Date('06-30-' + today.getFullYear().toString())
            );
            this.isCustom = false;
            break;
          case 'quaterThree':
            this.searchForm.controls.fromDate.setValue(
              new Date('07-01-' + today.getFullYear().toString())
            );
            this.searchForm.controls.toDate.setValue(
              new Date('09-30-' + today.getFullYear().toString())
            );
            this.isCustom = false;
            break;
          case 'quaterFour':
            this.searchForm.controls.fromDate.setValue(
              new Date('10-01-' + today.getFullYear().toString())
            );
            this.searchForm.controls.toDate.setValue(
              new Date('12-31-' + today.getFullYear().toString())
            );
            this.isCustom = false;
            break;
          case 'custom':
            this.searchForm.controls.fromDate.setValue('');
            this.searchForm.controls.toDate.setValue('');
            this.isCustom = true;
            break;
        }

      });
    this.searchForm
      .get('fromDate')
      ?.valueChanges.subscribe((selectedValue: any) => {
        this.minFromDate = selectedValue._d;
        this.searchForm.controls.toDate.setValue(new Date(this.minFromDate));
      });
    this.searchForm
      .get('designation')
      ?.valueChanges.subscribe((selectedValue: any) => {
        this.searchForm.controls.employeeId.setValue('All');
        this.getEmployeesForReportingManager();
      });
    this.Searchform();
    this.searchControlForEmp.valueChanges.subscribe((searchText: any) => {
      this.filterEmp(searchText);
    });
    this.searchControlForLeaveType.valueChanges.subscribe((searchText: any) => {
      this.filterForLeaveType(searchText);
    });
    this.searchControlForDesignation.valueChanges.subscribe((searchText: any) => {
      this.filterForDesignation(searchText);
    })
  }

  getLeaveTypes() {
    let obj = {
      tableName: 'lm_leavesmaster',
      status: 'Active',
      pageNumber: 1,
      pageSize: 1000,
      databaseName: this.companyDBName,
    };
    this.LM.getMastertable(obj).subscribe((result) => {
      if (result && result.status) {
        this.leaveTypes = result.data;
        this.filteredLeaveTypes = this.leaveTypes;
      }
    });
  }

  getDesignation() {
    let obj = {
      tableName: 'designationsmaster',
      status: 1,
      pageNumber: 1,
      pageSize: 1000,
      databaseName: this.companyDBName,
    };
    this.LM.getMastertable(obj).subscribe((result) => {
      if (result && result.status) {
        this.designations = result.data;
        this.filteredDesignations = this.designations;
      }
    });
  }

  getEmployeesForReportingManager() {
    let input = {
      managerId: this.userSession.id,
      departmentId: this.searchForm.controls.designation.value,
    };
    this.LM.getEmployeesForReportingManager(input).subscribe((result) => {
      if (result && result.status) {
        this.employeeDetails = result.data;
        this.filteredEmp = this.employeeDetails;
        if (this.employeeDetails.length > 0) {
          this.ishide = true;
        } else {
          this.ishide = false;
        }
      }
    });
  }
  Searchform() {
    this.arrayList = [];
    this.dataSource = new MatTableDataSource(this.arrayList);
    this.dataSource.paginator = this.paginator;
    this.dataSource.sort = this.sort;
    this.pageLoading = true;
    // this.paginator.firstPage();
    this.getPageSizes();
    this.spinner.show();
    let obj = {
      employeeId: this.searchForm.controls.employeeId.value,
      managerId: this.userSession.id,
      leaveType: this.searchForm.controls.leaveType.value,
      leaveStatus: this.searchForm.controls.leaveStatus.value,
      designation: this.searchForm.controls.designation.value,
      fromDate: this.pipe.transform(
        this.searchForm.controls.fromDate.value,
        'yyyy-MM-dd'
      ),
      toDate: this.pipe.transform(
        this.searchForm.controls.toDate.value,
        'yyyy-MM-dd'
      ),
      pageNumber: 1,
      pageSize: 1000,
    };
    this.LM.getEmployeeLeaveDetailedReportForManager(obj).subscribe(
      (result) => {
        this.spinner.hide();
        if (result.status) {
          this.arrayList = result.data;
          // this.count = this.arrayList[0].total;
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.paginator.pageSize = 5;
          this.dataSource.sort = this.sort;
          this.pageLoading = false;
        } else {
          this.arrayList = [];
          this.dataSource = new MatTableDataSource(this.arrayList);
          this.dataSource.paginator = this.paginator;
          this.dataSource.paginator.pageSize = 5;
          this.dataSource.sort = this.sort;
        }
      }
    );
  }
  resetform() {
    this.ngOnInit();
  }

  exportAsXLSX() {
    let fromDate = this.pipe.transform(
      this.searchForm.controls.fromDate.value,
      'dd-MM-yyyy'
    );
    let toDate = this.pipe.transform(
      this.searchForm.controls.toDate.value,
      'dd-MM-yyyy'
    );
    const ws: XLSX.WorkSheet = XLSX.utils.table_to_sheet(
      document.getElementById('table')
    );
    const wb: XLSX.WorkBook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Detailed_Report');

    /* save to file */
    XLSX.writeFile(wb, fromDate + '-' + toDate + '-' + 'Detailed_Report.xlsx');
  }
  getPageSizes(): number[] {
    var customPageSizeArray = [];
    if (this.dataSource.data.length > 5) {
      customPageSizeArray.push(5);
    }
    if (this.dataSource.data.length > 10) {
      customPageSizeArray.push(10);
    }
    if (this.dataSource.data.length > 20) {
      customPageSizeArray.push(20);
    }
    customPageSizeArray.push(this.dataSource.data.length);
    return customPageSizeArray;
  }

  filterEmp(searchText: any) {
    this.filteredEmp = this.employeeDetails.filter((val: any) =>
      val.empname.toLowerCase().includes(searchText.toLowerCase()) || val.employee_code.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredEmp.length <= 0) {
      this.searchControlForEmp.setValue('');
    }
  }
  filterForLeaveType(searchText: any) {
    this.filteredLeaveTypes = this.leaveTypes.filter((val: any) =>
      val.leavename.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredLeaveTypes.length <= 0) {
      this.searchControlForLeaveType.setValue('');
    }
  }
  filterForDesignation(searchText: any) {
    this.filteredDesignations = this.designations.filter((val: any) =>
      val.designation.toLowerCase().includes(searchText.toLowerCase()));
    if (this.filteredDesignations.length <= 0) {
      this.searchControlForDesignation.setValue('');
    }
  }

  generatePDF() {
  
    const doc = new jsPDF({ orientation: 'landscape' });
    const reportName = 'Leaves Detailed Report';
    let fromdate = (this.pipe.transform(this.searchForm.controls.fromDate.value, "dd-MM-YYYY"));
    let todate = (this.pipe.transform(this.searchForm.controls.toDate.value, "dd-MM-YYYY"));

    let manager = '';
    let locationName = '';
    let reportDate = fromdate +' to '+ todate;
    const headerHeight = 33;
    const tableData = this.arrayList.map((emp:  { 
      employee_code: any;    
      employee_name: any;    
      leavetype: any;  
      designation: any ;
      appliedon: any;   
      fromdate: any; 
      todate: any; 
      leavecount: any;
      leavestatus: any,
      approvedby: any,
    }, index: number) => [
     
        index + 1,
      emp.employee_code,
      emp.employee_name,
      emp.leavetype,
      emp.designation,
      this.datePipe.transform(emp.appliedon,'dd-MM-yyyy'),
      this.datePipe.transform(emp.fromdate,'dd-MM-yyy'),
      this.datePipe.transform(emp.todate,'dd-MM-yyyy'),
      emp.leavecount,
      emp.leavestatus,
      emp.approvedby,
    ]);
          autoTable(doc, {
            head: [['S.No.','Emp. ID','Emp. Name', 'Leave Type','Designation','Applied On','From','To','Days','Status','Approved By']],
            body:tableData,
            startY: headerHeight,
            styles: { fontSize: 10 },
            headStyles: { fontSize: 12 },
            margin: { top: headerHeight },
            didDrawPage: (data) => {
              this.pdfService.generatePDFHeader(doc, reportName,locationName,manager,reportDate,false,false);
              doc.setFontSize(10);
              doc.setTextColor(40);
            }
         });
       doc.save('Leaves_Detailed_Report.pdf');
  } 
}
